let queryCache={};
function searchIds(q){q=q.trim().toLowerCase();if(!q)return [];const exact=[],prefix=[],rest=[];for(const base of C.entries){const w=getWord(base.id),name=w.word.toLowerCase();let hay=queryCache[base.id];if(!hay||saved.edits[base.id])hay=[w.word,...w.meanings.map(m=>m.zh),...w.collocations.flat(),w.markdown||'',...(w.aliases||[])].join(' ').toLowerCase();queryCache[base.id]=hay;if(!hay.includes(q))continue;(name===q?exact:name.startsWith(q)?prefix:rest).push(w.id)}return [...exact,...prefix,...rest]}
function listPage(){const r=current(),filter=r.filter||'all',ids=filter==='stories'?C.entries.filter(w=>parseMarkdown(getWord(w.id).markdown).length).map(w=>w.id):filter==='edits'?Object.keys(saved.edits):C.entries.map(w=>w.id);return `<section class="subpage"><div class="heading"><h1>${filter==='stories'?'我的故事':filter==='edits'?'我修改的词':'完整词表'}</h1><p>按词族编排，不分学习等级。</p></div>${searchBox('','list-search')}${pageRows(ids,r.page||0)}</section>`}
function searchPage(){const r=current();return `<section class="subpage"><div class="heading"><h1>找一个词</h1><p>英文、中文、短语、故事都可以搜。</p></div>${searchBox(r.query||'')}<div id="search-results">${r.query?pageRows(searchIds(r.query),r.page||0):'<div class="empty">输入关键词开始搜索。</div>'}</div></section>`}
function familiesPage(){const q=(current().query||'').toLowerCase(),fs=C.families.filter(f=>(f.entry_ids.length>1||q)&&(f.root.toLowerCase().includes(q)||f.words.some(w=>w.toLowerCase().includes(q)))),p=current().page||0;return `<section class="subpage"><div class="heading"><h1>词族与主题组</h1><p>默认显示多个成员的组；独立词可通过搜索查找。</p></div>${searchBox(current().query||'','family-search','搜索词族、主题或成员')}<p class="muted" style="margin:12px 0">${fs.length} 组</p><div class="list">${fs.slice(p*50,p*50+50).map(f=>`<button class="word-row" data-route="${routeAttr({name:'family',id:f.id})}"><span><strong>${esc(f.root)}</strong><small>${esc(f.words.slice(0,5).join(' · '))}</small></span><span class="row-end">${f.entry_ids.length} 词</span></button>`).join('')}</div><div class="pager"><button class="secondary" data-page="${p-1}" ${p===0?'disabled':''}>上一页</button><small>${p+1} / ${Math.max(1,Math.ceil(fs.length/50))}</small><button class="secondary" data-page="${p+1}" ${(p+1)*50>=fs.length?'disabled':''}>下一页</button></div></section>`}
function familyPage(){const f=families.get(current().id);return `<section class="subpage"><div class="heading"><span class="pill">${esc(f.type)}</span><h1 style="margin-top:12px">${esc(f.root)}</h1><p>${f.entry_ids.length} 个词条</p></div><div class="list">${f.entry_ids.map(id=>row(id)).join('')}</div></section>`}
function settingsPage(){const group=(title,items)=>`<h2 class="settings-group-title">${title}</h2><div class="list settings-list">${items.map(([name,title,detail])=>`<button data-route="${routeAttr({name})}"><span><strong>${title}</strong><small>${detail}</small></span><span>›</span></button>`).join('')}</div>`;return `<section class="subpage"><div class="heading"><h1>设置</h1></div>${group('外观',[['themes','外观','界面语言、皮肤、字体与大小']])}${group('查找与浏览',[['search','搜索单词','英文、中文、短语和故事'],['wordlist','浏览词表',C.entries.length.toLocaleString()+' 个词'],['families','浏览词组','词族与主题组']])}${group('学习记录',[['history','浏览历史','最近浏览的单词'],['stats','学习统计','浏览与掌握情况'],['backup','学习记录备份','导出和恢复学习记录']])}${group('其他',[['about','版本与更新','版本、更新与来源']])}<div class="list settings-list" style="margin-top:18px"><button data-action="update-content"><span><strong>检查更新</strong><small id="cy-release-date">检查版本和更新时间</small></span><span>↻</span></button></div></section>`}
function themesPage(){return `<section class="subpage"><div class="heading"><h1>换一种心情。</h1><p>图片保留原画风，以小尺寸轻量格式显示。</p></div><div class="list settings-list" style="margin-bottom:18px"><button data-action="language"><span><strong>界面语言</strong><small>中文 / English</small></span><span>切换 ›</span></button><button data-action="shared-skins"><span><strong>快速换肤</strong><small>选择皮肤</small></span><span>◐</span></button></div><h2>皮肤与插画</h2><label class="panel row spread" style="margin-bottom:16px"><span><strong>随设备同步</strong><br><small>跟随系统浅色或深色模式</small></span><input type="checkbox" data-system-theme ${localStorage.getItem('cy-words-system-theme')==='1'?'checked':''}></label>${window.AndroidBridge?.setLauncher?`<label class="panel row spread" style="margin-bottom:16px"><span><strong>桌面图标同步皮肤</strong><br><small>关闭时使用固定图标</small></span><input type="checkbox" data-launcher-sync ${localStorage.getItem('cy-launcher-sync')==='1'?'checked':''}></label>`:''}${CYTheme.gallery()}<div class="panel" style="margin-top:18px"><h2>字体与大小</h2><div class="choice-row">${[[1,'标准'],[1.12,'大字'],[1.24,'特大']].map(([v,t])=>`<button data-scale="${v}" aria-pressed="${saved.settings.scale===v}">${t}</button>`).join('')}</div></div><div class="panel" style="margin-top:16px"><h2>${L('显示尺寸','Display sizes')}</h2>${sizeControls()}${meaningHtml(getWord(byName.get('resort')))}${illustrationHtml(getWord(byName.get('resort')))}</div><div class="panel row spread" style="margin-top:16px"><span>插画轻微移动与缩放</span><button class="secondary" data-action="motion" aria-pressed="${saved.settings.motion}">${saved.settings.motion?'已开启':'已关闭'}</button></div></section>`}
function historyPage(){const groups=new Map();for(const h of saved.history){const day=dayKey(new Date(h.at));if(!groups.has(day))groups.set(day,[]);groups.get(day).push(h)}return `<section class="subpage"><div class="heading"><h1>统计</h1><div class="list settings-list"><button data-route="${routeAttr({name:'stats'})}"><span><strong>学习统计</strong><small>浏览与掌握情况</small></span><span>›</span></button><button data-route="${routeAttr({name:'backup'})}"><span><strong>学习记录备份</strong><small>导出和恢复</small></span><span>›</span></button></div><p>最近浏览的 300 条记录。</p></div>${[...groups].map(([day,hs])=>`<h2 class="history-date">${day===dayKey()?'今天':day}</h2><div class="list">${hs.map(h=>row(h.id,new Date(h.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}))).join('')}</div>`).join('')||'<div class="empty">还没有浏览记录。</div>'}</section>`}
function statsPage(){const today=daily(),week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {name:['日','一','二','三','四','五','六'][d.getDay()],n:saved.daily[dayKey(d)]?.words.length||0}}),max=Math.max(1,...week.map(x=>x.n));return `<section class="subpage"><div class="heading"><h1>一点点，也算数。</h1><p>以当前设备的浏览记录计算。</p></div><div class="stat-grid">${[[Object.keys(saved.views).length,'已浏览单词'],[Object.keys(saved.mastered).length,'熟词'],[Object.values(saved.views).reduce((a,b)=>a+b,0),'总浏览次数'],[Object.keys(saved.edits).filter(id=>parseMarkdown(saved.edits[id].markdown).length).length,'自己写过故事的词']].map(([v,l])=>`<div class="panel"><div class="stat-value">${v}</div><div class="stat-label">${l}</div></div>`).join('')}</div><div class="panel" style="margin-top:17px"><div class="row spread"><h2>最近七天</h2><small>今天 ${today.words.length} 个词 · ${Math.floor(today.seconds/60)} 分钟</small></div><div class="week">${week.map(d=>`<div>${d.n}<div class="week-bar"><i style="height:${d.n/max*100}%"></i></div>${d.name}</div>`).join('')}</div></div><p class="footer-note">停留时间仅累计单词页处于前台且获得焦点的时段。已掌握由你手动标记。</p></section>`}
function editorData(id){const w=getWord(id);let d;try{d=JSON.parse(localStorage.getItem(DRAFT+id)||'null')}catch(e){}if(d&&!Array.isArray(d.meanings))d=null;return {id,base:JSON.stringify(saved.edits[id]||null),ipa:w.ipa_us,meanings:w.meanings.map(m=>({...m})),collocations:w.collocations.map(p=>[...p]),markdown:w.markdown||'',note:w.note||'',drawing:w.drawing?structuredClone(w.drawing):null,...(d||{})}}
function editToWord(e){return {...getWord(e.id),ipa_us:e.ipa,meanings:e.meanings.filter(m=>m.zh.trim()).map((m,i)=>({...m,zh:m.zh.trim(),primary:i===0})),drawing:CY_ART.normalizeScene(e.drawing),collocations:e.collocations.filter(p=>p[0].trim()||p[1].trim()).map(p=>p.map(t=>t.trim())),markdown:e.markdown,note:e.note||''}}
function previewEditor(){if(!EDITOR||!editor)return;const w=editToWord(editor);document.getElementById('editor-preview').innerHTML=`<h2>${L('内容预览','Live preview')}</h2>${meaningHtml(w)}${illustrationHtml(w)}${storyHtml(w)}${collocationsHtml(w)}`}
function editorPage(){return EDITOR?storyHtml(getWord(current().id)):'';if(!EDITOR)return '';const id=current().id;if(!editor||editor.id!==id)editor=editorData(id);const e=editor,w=words.get(id);window.CY_EDITOR_KIT?.begin(e);return `<section><div class="heading"><h1>${esc(w.word)}</h1><p>${L('直接填写下面的输入栏，修改后自动保存。右侧可随时查看效果。','Edit the fields below. Changes save automatically, with a live preview alongside.')}</p></div>${window.CY_EDITOR_KIT?.toolbar()||''}${window.CY_EDITOR_KIT?.panel()||''}<details class="editor-size-options"><summary>${L('调整显示尺寸','Adjust display sizes')}</summary>${sizeControls()}</details><div class="editor-grid"><div class="editor-fields"><label for="edit-ipa">美式音标</label><input id="edit-ipa" data-edit="ipa" value="${esc(e.ipa)}"><div class="section-title"><h2>中文释义</h2><button class="secondary" data-action="add-meaning">＋ 添加义项</button></div><div class="meaning-edit-rows">${e.meanings.map((m,i)=>`<div class="meaning-edit-row"><input class="pos-input" data-meaning-pos="${i}" aria-label="词性" value="${esc(m.pos)}" list="pos-options"><input data-meaning-zh="${i}" aria-label="中文释义" value="${esc(m.zh)}"><button class="delete-row" data-action="remove-meaning" data-index="${i}" aria-label="删除">×</button><label class="join-sense"><input type="checkbox" data-meaning-join="${i}" ${i>0&&m.sense_group&&m.sense_group===e.meanings[i-1].sense_group?'checked':''} ${i===0?'disabled':''}>${L('与上一义合并','Join the previous sense')}</label></div>`).join('')}</div><datalist id="pos-options">${['n.','v.','vi.','vt.','adj.','adv.','prep.','conj.','pron.','num.','interj.','phr.'].map(p=>`<option value="${p}">`).join('')}</datalist><label for="edit-note">补充说明（可编辑）</label><textarea id="edit-note" data-edit="note">${esc(e.note||'')}</textarea><label for="edit-story">单词故事与提示</label><div class="markdown-tools"><button data-insert="highlight">高亮</button><button data-insert="bold">粗体</button><button data-insert="tip">@ 提示</button><button data-insert="root">/ 构词</button></div><textarea id="edit-story" data-edit="markdown" placeholder="- 一个小故事\n- @记忆提示\n- /构词联想\n==高亮== · **粗体**">${esc(e.markdown)}</textarea><p class="draft-hint" id="draft-status">${L('修改会自动保存；也可点“保存并返回”。','Changes save automatically. Use Save & return when finished.')}</p><div class="editor-actions"><button class="primary" data-action="save-edit">保存并返回</button><button class="secondary" data-action="discard-edit">撤销本机修改</button></div><div class="section-title"><h2>${L('短语与搭配','Phrases & collocations')}</h2><button class="secondary" data-action="add-phrase">＋ 添加搭配</button></div><div class="phrase-edit-rows">${e.collocations.map((p,i)=>`<div class="phrase-edit-row"><input data-phrase-en="${i}" aria-label="英文短语" placeholder="英文短语" value="${esc(p[0])}"><input data-phrase-zh="${i}" aria-label="中文翻译" placeholder="中文翻译" value="${esc(p[1])}"><button class="delete-row" data-action="remove-phrase" data-index="${i}" aria-label="删除">×</button></div>`).join('')}</div></div><div class="editor-preview" id="editor-preview"></div></div></section>`}
function saveEdit(force=false,stay=false){if(!EDITOR||!editor)return;const latest=readState(),currentBase=JSON.stringify(latest.edits[editor.id]||null);if(!force&&currentBase!==editor.base){if(stay){document.getElementById('draft-status').textContent=L('另一个窗口已修改这个词，请核对后保存。','This word changed in another window. Review before saving.');return;}showModal('另一个窗口已修改这个词','你的草稿还在。可以取消后核对，也可以使用当前内容覆盖本机这个词的修改。','使用当前内容',()=>saveEdit(true));return}const w=editToWord(editor);if(!w.meanings.length||w.collocations.some(p=>!p[1])){toast('请保留至少一条词义，并为每条搭配填写中文翻译。');return}const base={...words.get(w.id),...(S.words[w.id]||{})},patch={};if(w.ipa_us!==base.ipa_us)patch.ipa_us=w.ipa_us;if(JSON.stringify(w.meanings.map(m=>[m.zh,m.pos,!!m.primary,m.sense_group||'']))!==JSON.stringify(base.meanings.map(m=>[m.zh,m.pos,!!m.primary,m.sense_group||''])))patch.meanings=w.meanings;if(JSON.stringify(w.collocations)!==JSON.stringify(base.collocations))patch.collocations=w.collocations;if(w.note!==(base.note||''))patch.note=w.note;if(w.markdown!==(base.markdown||''))patch.markdown=w.markdown;if(JSON.stringify(w.drawing||null)!==JSON.stringify(base.drawing||null))patch.drawing=w.drawing;if(Object.keys(patch).length)latest.edits[w.id]=patch;else delete latest.edits[w.id];saved=latest;put();localStorage.removeItem(DRAFT+w.id);queryCache={};if(stay){editor.base=JSON.stringify(readState().edits[w.id]||null);editor.savedDraft=JSON.stringify([editor.ipa,editor.meanings,editor.collocations,editor.markdown,editor.drawing||null]);draftEditor();return}toast('已保存到本机。');editor=null;finishEditor(w.id)}
function finishEditor(id){const previous=stack[stack.length-2];if(previous?.name==='word'&&previous.id===id)back();else go({name:'word',id},true)}
function backupPage(){if(!EDITOR)return publicBackupPage();return `<section class="subpage"><div class="heading"><h1>把故事留好。</h1><p>电脑、网页版和安卓之间，可以用备份文件转移个人修改。</p></div><div class="panel backup-actions"><button class="primary" data-action="export">导出全部个人数据</button><button class="secondary" data-action="export-stories">导出故事 Markdown</button><button class="secondary" data-action="import">导入备份 / 旧版备份</button><button class="text-button" data-route="${routeAttr({name:'wordlist',filter:'edits'})}">浏览我修改过的词 →</button><input class="hidden" id="import-file" type="file" accept=".json,application/json"></div><p class="footer-note">可以一边打开页面查看，一边让我修改公开词库或故事；发布后刷新即可。你的个人修改优先显示。若也修改了同一词，可撤销本机修改以查看网站版本。<br>个人编辑不会自动上传到公共网站。需要合入新版时，将备份或故事文件发给我即可。此版不提供跨设备个人数据自动云同步。</p></section>`}
function aboutPage(){return aboutPageV3();return `<section class="subpage"><div class="heading"><h1>吹衣单词 0.5.1</h1><p>完整词库 · 同屏记忆</p></div><div class="panel"><p>原库 7,298 词，经补充、合并和剔除后，共 ${C.entries.length.toLocaleString()} 词、23,976 条独立短语与搭配，全部带中文翻译。没有难度分级。</p><p class="footer-note">词义、搭配与词族沿用已整理数据，完成结构检查和重点核对，仍可继续修订；不等同逐条权威词典审校。</p><p class="footer-note">插画延续复古绘本风扁平画法。六张小图合计约 50 KB，每张 320×213；只为已有故事的六词配图。动效是轻微位移缩放，可在设置关闭。</p><p class="footer-note">来源：<a href="https://github.com/designfuchen/word-atlas" data-external>Word Atlas contributors（词光）</a>，<a href="https://creativecommons.org/licenses/by/4.0/" data-external>CC BY 4.0</a>。本版改动：取消分级及例句、补词、拆分义项、词族归组、带译搭配、重点音标修订，并加入个人记忆内容。</p><p class="footer-note">公开词库与故事可通过版本更新发布；自己的编辑、历史、皮肤和统计保存在当前设备。更新安卓客户端可覆盖安装。</p></div></section>`}
function render(restore=false){applyTheme();if(current().name==='editor'&&!EDITOR)stack=[{name:'home',scroll:0}];const pages={home:homePage,word:wordPage,settings:settingsPage,wordlist:listPage,search:searchPage,families:familiesPage,family:familyPage,history:historyPage,stats:statsPage,themes:themesPage,...(EDITOR?{editor:editorPage,phrases:phrasesPage}:{}),backup:backupPage,about:aboutPage,stories:storiesPage,story:storyPage,day:dayPage,completed:completedPage,recent:recentPage,books:booksPage};app.innerHTML=header()+`<main class="main">${updateAvailable?'<div class="update-banner"><span>网站有新内容；草稿已保存在本机。</span><button data-action="reload">刷新查看</button></div>':''}${(pages[current().name]||homePage)()}</main>`+nav();if(current().name==='editor'&&EDITOR)previewEditor();window.CY_EDITOR_KIT?.mount();nativeBack();if(restore)requestAnimationFrame(()=>scrollTo(0,current().scroll||0));lastClock=Date.now()}
function flushTime(){const now=Date.now(),seconds=Math.floor((now-lastClock)/1000);lastClock=now;if(seconds>0&&!document.hidden&&(document.hasFocus()||window.AndroidBridge)&&current().name==='word'){saved=readState();daily().seconds+=Math.min(seconds,15);put()}}
function speak(id){const word=getWord(id).word;try{if(window.AndroidBridge?.speak)return window.AndroidBridge.speak(word);if(window.speechSynthesis){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(word);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u);return}}catch(e){}toast('当前设备没有可用的英语语音。')}
function download(text,name,mime='application/json'){if(window.AndroidBridge?.exportData){window.AndroidBridge.exportData(text,name,mime);return}const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){flushTime();download(JSON.stringify({format:'chuiyi-words-backup',version:2,contentVersion:C.version,data:readState()},null,2),'吹衣单词_个人备份_'+dayKey()+'.json')}
function exportStories(){const ids=new Set([...Object.keys(S.words),...Object.keys(saved.edits)]),text=[...ids].map(id=>getWord(id)).filter(w=>parseMarkdown(w.markdown).length).map(w=>'- **'+w.word+'**\n'+w.markdown.split('\n').filter(l=>!/^\s*-?\s*\*\*[^*]+\*\*\s*$/.test(l)).join('\n')).join('\n\n');download(text,'吹衣单词_记忆故事.md','text/markdown')}
function importData(text){let v,data;try{v=JSON.parse(text);if(v.format!=='chuiyi-words-backup'||![1,2].includes(v.version)||!v.data)throw Error();if(v.version===1){data=fresh();const o=v.data;data.settings=o.settings||data.settings;for(const [name,t]of Object.entries(o.overrides||{})){const id=byName.get(name);if(id)data.edits[id]={markdown:t}}for(const h of o.history||[]){const id=byName.get(h.id);if(id)data.history.push({...h,id})}for(const [name,n]of Object.entries(o.views||{})){const id=byName.get(name);if(id)data.views[id]=n}for(const name of Object.keys(o.mastered||{})){const id=byName.get(name);if(id&&o.mastered[name])data.mastered[id]=true}data.lastWord=byName.get(o.lastWord);for(const [day,d]of Object.entries(o.daily||{}))data.daily[day]={seconds:d.seconds||0,words:(d.words||[]).map(id=>byName.get(id)).filter(Boolean)}}else data=v.data;data=normalize(data)}catch(e){toast('不是有效的吹衣单词备份。');return false}showModal('恢复这份备份？','将替换当前设备的个人修改、历史、皮肤和统计。恢复前可以先取消并导出当前数据。','恢复备份',()=>{saved=data;put();queryCache={};editor=null;stack=[{name:'home',scroll:0}];sync(true);render();scrollTo(0,0);toast('备份已恢复。')});return true}
async function checkUpdate(){if(window.AndroidBridge?.checkUpdates){window.AndroidBridge.checkUpdates(S.version||C.version);return}if(location.protocol==='file:'){toast('电脑文件可直接打开；在线更新请使用网页版。');return}try{const r=await fetch('version.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error();const v=await r.json();if(v.contentVersion!==(S.version||C.version)){updateAvailable=true;snapshot();render(true)}else toast('当前已是最新内容。')}catch(e){toast('暂时无法检查更新，离线内容仍可使用。')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-route],[data-word],[data-tab],[data-page],button[data-theme],button[data-scale],[data-external]');if(!b||b.disabled)return;
 if(b.hasAttribute('data-external')){if(window.AndroidBridge?.openLink){e.preventDefault();window.AndroidBridge.openLink(b.href)}return}
 if(b.dataset.word){openWord(b.dataset.word);return}if(b.dataset.route){const r=JSON.parse(b.dataset.route);if(r.name==='editor'&&current().name==='editor')return;go(r);return}if(b.dataset.tab){b.dataset.tab==='home'?home():current().name!==b.dataset.tab&&go({name:b.dataset.tab});return}
 if(b.dataset.page!==undefined){current().page=Number(b.dataset.page);sync(true);render();scrollTo(0,0);return}if(b.dataset.theme){saved=readState();saved.settings.theme=b.dataset.theme;window.CYTheme?.set(b.dataset.theme);put();snapshot();render(true);return}if(b.dataset.scale){saved=readState();saved.settings.scale=Number(b.dataset.scale);put();snapshot();render(true);return}
 switch(b.dataset.action){case 'shared-skins':window.CYTheme?.picker(b);break;case 'language':window.ChuiyiI18n?.setLanguage(window.ChuiyiI18n.lang==='en'?'zh':'en');break;case 'reset-sizes':saved.settings.posScale=1;saved.settings.artScale=1;applyTheme();put();render(true);break;case 'copy-draft':if(editor)copyText(editor.markdown);break;case 'delete-book-word':if(EDITOR)deleteBookWord(b.dataset.id);break;case 'menu':toggleMenu();break;case 'copy-word':copyWord();closeMenu();break;case 'copy-entry':copyEntry();closeMenu();break;case 'copy-meanings':copyText(getWord(current().id).meanings.map(m=>m.pos+' '+m.zh).join('\n'));closeMenu();break;case 'add-meaning':if(EDITOR){editor.meanings.push({pos:'n.',zh:'',primary:false,sense_group:''});refreshEditor()}break;case 'remove-meaning':if(EDITOR&&editor.meanings.length>1){editor.meanings.splice(+b.dataset.index,1);refreshEditor();scheduleAutoSave()}break;case 'add-phrase':if(EDITOR){editor.collocations.push(['','']);refreshEditor()}break;case 'remove-phrase':if(EDITOR){editor.collocations.splice(+b.dataset.index,1);refreshEditor();scheduleAutoSave()}break;case 'back':back();break;case 'cancel':closeModal();break;case 'confirm':{const fn=modal;closeModal();fn?.();break}case 'master':saved=readState();saved.mastered[b.dataset.id]?delete saved.mastered[b.dataset.id]:saved.mastered[b.dataset.id]=true;put();snapshot();render(true);break;case 'motion':saved=readState();saved.settings.motion=!saved.settings.motion;put();snapshot();render(true);break;case 'speak':speak(b.dataset.id);break;case 'save-edit':if(EDITOR)saveEdit();break;case 'discard-edit':showModal('撤销这个词的本机修改？','恢复网站自带的词义、搭配和故事。其他词的修改不受影响。','撤销修改',()=>{const id=current().id;saved=readState();delete saved.edits[id];put();localStorage.removeItem(DRAFT+id);editor=null;queryCache={};finishEditor(id)});break;case 'export':exportData();break;case 'export-stories':exportStories();break;case 'import':window.AndroidBridge?.importData?window.AndroidBridge.importData():document.getElementById('import-file').click();break;case 'reload':location.reload();break;case 'update-content':checkUpdate();break;case 'previous-word':case 'next-word':{const ids=studyWords(),i=ids.indexOf(current().id)+(b.dataset.action==='next-word'?1:-1);if(ids[i])openWord(ids[i],true);break}}
});
let inputTimer;
document.addEventListener('input',e=>{const t=e.target;if(EDITOR&&(t.dataset.edit||t.dataset.meaningPos!==undefined||t.dataset.meaningZh!==undefined||t.dataset.phraseEn!==undefined||t.dataset.phraseZh!==undefined)&&editor){if(t.dataset.edit)editor[t.dataset.edit]=t.value;else if(t.dataset.meaningPos!==undefined)editor.meanings[+t.dataset.meaningPos].pos=t.value;else if(t.dataset.meaningZh!==undefined)editor.meanings[+t.dataset.meaningZh].zh=t.value;else if(t.dataset.phraseEn!==undefined)editor.collocations[+t.dataset.phraseEn][0]=t.value;else if(t.dataset.phraseZh!==undefined)editor.collocations[+t.dataset.phraseZh][1]=t.value;try{window.CY_EDITOR_KIT?.record();localStorage.setItem(DRAFT+editor.id,JSON.stringify(editor));document.getElementById('draft-status').textContent='草稿已自动保存在本机。'}catch(e){toast('草稿保存失败，请立即导出。')}previewEditor();scheduleAutoSave();return}if(t.id==='search-input'){current().query=t.value;current().page=0;sync(true);clearTimeout(inputTimer);document.getElementById('search-results').innerHTML='<div class="empty">正在搜索…</div>';inputTimer=setTimeout(()=>{const box=document.getElementById('search-results');if(!box||current().name!=='search')return;box.innerHTML=t.value?pageRows(searchIds(t.value)):'<div class="empty">输入关键词开始搜索。</div>'},140)}if(t.id==='family-search'){current().query=t.value;current().page=0;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{if(current().name!=='families')return;const p=t.selectionStart;sync(true);render();const el=document.getElementById('family-search');el.focus();el.setSelectionRange(p,p)},200)}});
document.addEventListener('focusin',e=>{if(['home-search','list-search'].includes(e.target.id)){const q=e.target.value;go({name:'search',query:q});const el=document.getElementById('search-input');el.focus()}});
document.addEventListener('change',async e=>{if(e.target.id==='import-file'&&e.target.files[0]){const f=e.target.files[0];if(f.size>50*1024*1024){toast('备份过大，请核对文件。');return}importData(await f.text());e.target.value=''}});
addEventListener('storage',e=>{if(e.key!==KEY)return;if(EDITOR&&JSON.stringify(JSON.parse(e.newValue||'{}').deletedWords||{})!==JSON.stringify(saved.deletedWords||{})){location.reload();return}saved=readState();queryCache={};if(current().name==='editor'){document.getElementById('draft-status').textContent='另一个窗口的数据已更新；你的当前草稿仍保留，保存时会检查冲突。'}else{snapshot();render(true)}});
addEventListener('keydown',e=>{if(e.key==='Escape'&&(closeMenu()||back()))e.preventDefault()});addEventListener('pagehide',()=>{flushTime()});document.addEventListener('visibilitychange',()=>{if(document.hidden)flushTime();else lastClock=Date.now()});setInterval(flushTime,5000);
window.ChuiyiWords={back,importData,exportData,parseMarkdown,suspend:flushTime,resume(){lastClock=Date.now()},toast};
if(EDITOR)window.CY_EDITOR_KIT?.connect({get:()=>editor,baseImage:()=>getWord(editor.id).image,publishData(){if(editor){const currentState=readState();if(JSON.stringify(currentState.edits[editor.id]||null)!==editor.base)throw Error(L('另一个窗口已修改，请先解决保存冲突。','Resolve the editing conflict first.'));const w=editToWord(editor);if(!w.meanings.length||w.collocations.some(p=>!p[0]||!p[1]))throw Error(L('请先补全词义和短语翻译。','Complete meanings and phrase translations first.'));saveEdit(false,true)}return readState().edits},commit(){draftEditor();previewEditor();scheduleAutoSave()},redraw:refreshEditor,export:download});

function deleteBookWord(id){
 if(!EDITOR||!words.has(id))return false;
 const name=words.get(id).word;closeMenu();
 showModal('从词书删除「'+name+'」？','此词条及其词族、故事中的单词关联将被移除。导出的词书也不再包含它；可先取消并导出词书留存。','删除',()=>{
  const latest=readState();latest.deletedWords||={};latest.deletedWords[id]=true;
  const pruned=pruneBookWords(C,S,latest.deletedWords);latest.bookMeta=pruned.cleanMeta(latest.bookMeta||meta());latest.bookMeta.deletedWords={...latest.deletedWords};
  try{localStorage.setItem(KEY,JSON.stringify(latest))}catch(e){toast('删除失败：无法保存词书修改，请检查存储空间。');return}
  clearTimeout(autoSaveTimer);editor=null;localStorage.removeItem(DRAFT+id);
  Object.assign(C,pruned.catalog);Object.assign(S,pruned.shared);
  words.clear();byName.clear();families.clear();for(const w of C.entries){words.set(w.id,w);byName.set(w.word.toLowerCase(),w.id)}for(const f of C.families)families.set(f.id,f);
  saved=normalize(latest);queryCache={};allPhrases=null;lastClock=Date.now();put();
  stack=[{name:'home',scroll:0}];sync(true);render();scrollTo(0,0);toast('已从词书删除「'+name+'」');
 });return true;
}

// Book content is independent from personal study records.
const BOOK_NAME='吹衣词族故事1';
function meta(){return EDITOR&&saved.bookMeta?saved.bookMeta:(S.bookMeta||{name:BOOK_NAME,families:{},stories:[]})}
function editableMeta(){if(!EDITOR)return null;if(!saved.bookMeta)saved.bookMeta=structuredClone(meta());saved.bookMeta.families||={};saved.bookMeta.stories||=[];return saved.bookMeta}
function familyMeta(id){return meta().families?.[id]||{}}
function level(f){const d=Number(familyMeta(f.id).difficulty);if([1,2,3].includes(d))return d;const min=Math.min(...f.words.map(w=>w.length));return f.type==='主题组'||min<=4?1:min<=7?2:3}
function hashOrder(id,seed){let n=2166136261+seed*7919;for(const c of id)n=Math.imul(n^c.charCodeAt(0),16777619);return n>>>0}
function orderedFamilies(){const opts=saved.learning||{},list=C.families.filter(f=>opts.difficulty==='all'||!opts.difficulty||String(level(f))===opts.difficulty);return list.sort((a,b)=>opts.order?.startsWith('random')?hashOrder(a.id,+opts.order.slice(-1))-hashOrder(b.id,+opts.order.slice(-1)):level(a)-level(b)||Math.min(...a.words.map(w=>w.length))-Math.min(...b.words.map(w=>w.length))||a.id.localeCompare(b.id))}
function studyWords(){const fs=orderedFamilies(),out=[],buckets=fs.map(f=>[...f.entry_ids]);for(let i=0; buckets.some(b=>i<b.length);i++)for(const b of buckets)if(b[i])out.push(b[i]);return out}
function storyList(){return Array.isArray(meta().stories)?meta().stories:[]}
function studyControls(){const o=saved.learning||{};return `<div class="study-controls"><label>查看<select data-learning="mode">${[['words','单词'],['families','词族'],['stories','故事']].map(([v,t])=>`<option value="${v}" ${o.mode===v?'selected':''}>${t}</option>`).join('')}</select></label><label>难度<select data-learning="difficulty">${[['all','全部'],['1','基础'],['2','进阶'],['3','较难']].map(([v,t])=>`<option value="${v}" ${o.difficulty===v?'selected':''}>${t}</option>`).join('')}</select></label><label>顺序<select data-learning="order">${[['difficulty','难度顺序'],['random1','随机①'],['random2','随机②'],['random3','随机③']].map(([v,t])=>`<option value="${v}" ${o.order===v?'selected':''}>${t}</option>`).join('')}</select></label></div>`}
function doneButton(kind,id){return `<button class="secondary" data-done="${kind}" data-id="${esc(id)}" aria-pressed="${!!saved.completed?.[kind]?.[id]}">${saved.completed?.[kind]?.[id]?'✓ 已完成':'标记完成'}</button>`}
function pager048(items,renderRow,size=50){const p=Math.max(0,Math.min(current().page||0,Math.max(0,Math.ceil(items.length/size)-1)));return `<p class="muted">${items.length} 项</p><div class="list">${items.slice(p*size,p*size+size).map(renderRow).join('')||'<p class="empty">暂无内容</p>'}</div><div class="pager"><button class="secondary" data-page="${p-1}" ${p===0?'disabled':''}>上一页</button><small>${p+1} / ${Math.max(1,Math.ceil(items.length/size))}</small><button class="secondary" data-page="${p+1}" ${(p+1)*size>=items.length?'disabled':''}>下一页</button></div>`}
function familyRow(f){return `<button class="word-row" data-route="${routeAttr({name:'family',id:f.id})}"><span><strong>${esc(f.root)}</strong><small>${esc(f.words.slice(0,5).join(' · '))}</small></span><span class="row-end">${['','基础','进阶','较难'][level(f)]} · ${f.entry_ids.length}词${EDITOR?'<br>'+ (familyMeta(f.id).ready?'✓ 整理完成':'未完成'):''}</span></button>`}
function storyRow(s){return `<button class="word-row" data-route="${routeAttr({name:'story',id:s.id})}"><span><strong>${esc(s.title)}</strong><small>${(s.entry_ids||[]).length} 个单词</small></span><span>›</span></button>`}
homePage=function(){const ids=studyWords(),last=ids.includes(saved.lastWord)?saved.lastWord:ids[0],w=last?getWord(last):null;const mode=saved.learning?.mode||'words';return `<section class="subpage"><div class="home-head"><div><h1>${esc(meta().name||BOOK_NAME)}</h1><p>${C.entries.length} 个单词 · ${C.families.length} 个词族</p></div><div class="home-stamp" aria-hidden="true">词</div></div>${searchBox('','home-search')}${studyControls()}${w?`<button class="panel continue" data-word="${last}"><span><small>${saved.lastWord===last?'继续上次浏览':'开始学习'}</small><strong>${esc(w.word)}</strong></span><span>→</span></button>`:'<p class="empty">当前分类没有单词</p>'}${mode==='families'?familyFilters()+pager048(filterReady(orderedFamilies()),familyRow):mode==='stories'?storyTools()+pager048(storyList().filter(s=>!saved.learning?.difficulty||saved.learning.difficulty==='all'||(s.entry_ids||[]).some(id=>ids.includes(id))),storyRow):pager048(ids,id=>row(id))}</section>`}
function familyFilters(){if(!EDITOR)return '';const fs=orderedFamilies(),yes=fs.filter(f=>familyMeta(f.id).ready).length;return `<div class="filter-row">${[['all','全部',fs.length],['todo','未完成',fs.length-yes],['ready','已完成',yes]].map(([v,t,n])=>`<button class="secondary" data-ready-filter="${v}" aria-pressed="${(current().ready||'all')===v}">${t} ${n}</button>`).join('')}</div>`}
function filterReady(fs){return !EDITOR||!current().ready||current().ready==='all'?fs:fs.filter(f=>!!familyMeta(f.id).ready===(current().ready==='ready'))}
familiesPage=function(){const q=(current().query||'').toLowerCase();return `<section class="subpage"><h1>词族</h1>${studyControls()}${searchBox(current().query||'','family-search','搜索词族或成员')}${familyFilters()}${pager048(filterReady(orderedFamilies()).filter(f=>f.root.toLowerCase().includes(q)||f.words.some(w=>w.toLowerCase().includes(q))),familyRow)}</section>`}
function storyBody(text){return `<div class="story-text">${rich(text||'暂未添加故事。')}</div>`}
familyPage=function(){const f=families.get(current().id);if(!f)return '<p>找不到这个词族</p>';const m=familyMeta(f.id);return `<section class="subpage"><div class="heading"><h1>${esc(f.root)}</h1><p>${f.entry_ids.length} 个单词 · ${['','基础','进阶','较难'][level(f)]}</p>${doneButton('families',f.id)}</div><section class="panel"><h2>词族故事</h2>${storyBody(m.story)}${EDITOR?`<details class="book-editor" ${current().edit?'open':''}><summary>编辑词族故事与整理状态</summary><label>词族故事<textarea data-meta="family-story" data-id="${f.id}">${esc(m.story||'')}</textarea></label><label>难度<select data-meta="family-difficulty" data-id="${f.id}">${[1,2,3].map(n=>`<option value="${n}" ${level(f)===n?'selected':''}>${['','基础','进阶','较难'][n]}</option>`).join('')}</select></label><label><input type="checkbox" data-meta="family-ready" data-id="${f.id}" ${m.ready?'checked':''}>整理完成</label><small data-meta-status>修改后自动保存</small></details>`:''}</section><h2>词族成员</h2><div class="list">${f.entry_ids.map(id=>row(id)).join('')}</div></section>`}
function storyLinks(w){const ss=storyList().filter(s=>s.entry_ids?.includes(w.id));return ss.length?ss.map(s=>`<button class="secondary story-entry" data-route="${routeAttr({name:'story',id:s.id})}">故事族 · ${esc(s.title)}</button>`).join(''):EDITOR?`<button class="secondary story-entry" data-route="${routeAttr({name:'stories',word:w.id})}">加入故事族</button>`:''}
function storyTools(){return EDITOR?'<div class="filter-row"><button class="secondary" data-book-action="new-story">＋ 新建故事</button></div>':''}
function storiesPage(){return `<section class="subpage"><h1>故事分类</h1>${current().word?`<p>选择故事加入 ${esc(words.get(current().word)?.word)}</p>`:''}${storyTools()}${pager048(storyList(),s=>current().word?`<div class="panel row spread">${storyRow(s)}<button class="secondary" data-book-action="add-current" data-id="${esc(s.id)}">加入</button></div>`:storyRow(s))}</section>`}
function storyPage(){const s=storyList().find(s=>s.id===current().id);if(!s)return '<p>找不到这个故事</p>';return `<section class="subpage"><h1>${esc(s.title)}</h1>${doneButton('stories',s.id)}<div class="panel">${storyBody(s.text)}</div>${EDITOR?`<details class="book-editor"><summary>编辑故事与单词归属</summary><label>故事名称<input data-meta="story-title" data-id="${esc(s.id)}" value="${esc(s.title)}"></label><label>故事正文<textarea data-meta="story-text" data-id="${esc(s.id)}">${esc(s.text||'')}</textarea></label><label>搜索单词加入<input id="story-member-search" type="search" placeholder="输入英文或中文"></label><div id="story-member-results" class="manage-members"></div><p class="muted">下面的单词可调整顺序或移出；单词本身保留。</p><div class="manage-members">${(s.entry_ids||[]).map((id,i)=>`<div class="row spread"><span>${esc(words.get(id)?.word)}</span><div><button class="secondary" data-book-action="up" data-id="${esc(s.id)}" data-word-id="${id}" ${i===0?'disabled':''}>↑</button><button class="secondary" data-book-action="down" data-id="${esc(s.id)}" data-word-id="${id}" ${i===s.entry_ids.length-1?'disabled':''}>↓</button><button class="secondary" data-book-action="remove-member" data-id="${esc(s.id)}" data-word-id="${id}">移出</button></div></div>`).join('')}</div><small data-meta-status>修改后自动保存</small><button class="secondary" data-book-action="delete-story" data-id="${esc(s.id)}">删除故事</button></details>`:''}<div class="list">${(s.entry_ids||[]).filter(id=>words.has(id)).map(id=>row(id)).join('')}</div></section>`}
const originalWordPage048=wordPage;
wordPage=function(){return originalWordPage048().replace('<div class="word-memory">','<div class="word-memory">'+doneButton('words',current().id))}
function recordLinks(){return `<div class="list settings-list">${[['stats','学习统计'],['completed','已完成的词／词族／故事'],['recent','历史'],['backup','学习记录备份'],['books','词书导入导出']].map(([name,title])=>`<button data-route="${routeAttr({name})}"><span>${title}</span><span>›</span></button>`).join('')}</div>`}
historyPage=function(){return `<section class="subpage"><h1>统计</h1>${recordLinks()}</section>`}
function recentPage(){const hs=[...new Map(saved.history.map(h=>[h.id,h])).values()].sort((a,b)=>b.at-a.at);return `<section class="subpage"><h1>历史</h1>${pager048(hs,h=>row(h.id,new Date(h.at).toLocaleString('zh-CN')))}</section>`}
statsPage=function(){const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const day=dayKey(d);return {day,n:saved.daily[day]?.words.length||0}}),max=Math.max(1,...week.map(d=>d.n)),seen=new Set([...Object.keys(saved.views),...Object.values(saved.daily).flatMap(d=>d.words)]);return `<section class="subpage"><h1>学习统计</h1><div class="stat-grid"><div class="panel"><div class="stat-value">${seen.size}</div>已浏览单词</div>${['words','families','stories'].map((k,i)=>`<button class="panel" data-route="${routeAttr({name:'completed',kind:k})}"><div class="stat-value">${Object.keys(saved.completed?.[k]||{}).length}</div>${['完成单词','完成词族','完成故事'][i]}</button>`).join('')}</div><section class="panel"><h2>最近七天</h2><p class="muted">点击日期柱状图查看当天单词</p><div class="week">${week.map(d=>`<button aria-label="${d.day}，${d.n}个单词" data-route="${routeAttr({name:'day',day:d.day})}">${d.n}<div class="week-bar"><i style="height:${d.n/max*100}%"></i></div>${d.day.slice(5)}</button>`).join('')}</div></section><label>查看日期 <input type="date" data-stat-date value="${dayKey()}"></label>${recordLinks()}</section>`}
function dayPage(){const date=current().day,ids=saved.daily[date]?.words||[];return `<section class="subpage"><h1>${esc(date)}</h1><p>当天学习 ${ids.length} 个单词</p>${pager048(ids,id=>row(id))}</section>`}
function completedPage(){const kind=['words','families','stories'].includes(current().kind)?current().kind:'words',ids=Object.keys(saved.completed?.[kind]||{});return `<section class="subpage"><h1>已完成</h1><div class="filter-row">${[['words','单词'],['families','词族'],['stories','故事']].map(([k,t])=>`<button class="secondary" data-route="${routeAttr({name:'completed',kind:k})}" aria-pressed="${k===kind}">${t} ${Object.keys(saved.completed?.[k]||{}).length}</button>`).join('')}</div>${pager048(ids,id=>kind==='words'?row(id):kind==='families'&&families.has(id)?familyRow(families.get(id)):storyList().some(s=>s.id===id)?storyRow(storyList().find(s=>s.id===id)):'')}</section>`}
const settings048=settingsPage;settingsPage=function(){return settings048().replace('</section>',`<h2 class="settings-group-title">词书</h2><div class="list settings-list"><button data-route="${routeAttr({name:'books'})}">词书导入导出 ›</button></div></section>`).replace('最近浏览的单词','学习统计、完成记录与历史')}
