function booksPage(){return `<section class="subpage"><h1>词书导入导出</h1><p>${esc(meta().name||BOOK_NAME)}</p><p class="muted">包含全部单词、词族、单词故事、词族故事、故事分类及整理状态。</p><div class="panel backup-actions"><button class="primary" data-book-action="export-book">导出完整词书</button><button class="secondary" data-book-action="import-book">导入词书</button><input id="book-file" type="file" accept=".json,application/json" class="hidden"></div></section>`}
