function voiceDeleted048(){return localStorage.getItem('cy-voice-deleted')==='1'}
function autoVoice048(){return localStorage.getItem('cy-auto-voice')!=='0'&&!voiceDeleted048()}
function voiceDBOpen048(){if(!window.indexedDB)return Promise.reject(Error('当前环境不支持语音存储'));if(voiceDB048)return Promise.resolve(voiceDB048);return new Promise((resolve,reject)=>{const r=indexedDB.open('chuiyi-voice-packs',1);r.onupgradeneeded=()=>r.result.createObjectStore('packs');r.onsuccess=()=>{voiceDB048=r.result;resolve(r.result)};r.onerror=()=>reject(r.error)})}
async function voiceStore048(value){const db=await voiceDBOpen048();return new Promise((resolve,reject)=>{const tx=db.transaction('packs','readwrite'),st=tx.objectStore('packs');value?st.put(value,'current'):st.delete('current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
